import{_ as r,a0 as l,w as i,s as p,I as n,x as t,a1 as a,A as o,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"真的超讚！用systemd命令來管理linux系統！ | LCTT x X-CMD","titleTemplate":false,"description":"真的超讚！用systemd命令來管理linux系統！ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"真的超讚！用systemd命令來管理linux系統！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"真的超讚！用systemd命令來管理linux系統！ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140901 Awesome systemd Commands to Manage Linux System","title":"真的超讚！用systemd命令來管理linux系統！","tag":"201409","desc":""},"relativePath":"201409/20140901 Awesome systemd Commands to Manage Linux System.md","filePath":"[post].md"}'),m={name:"201409/20140901 Awesome systemd Commands to Manage Linux System.md"};function c(h,e,g,y,x,u){const s=l("Link");return i(),p("div",null,[e[18]||(e[18]=n("h1",{id:"真的超讚-用systemd命令來管理linux系統",tabindex:"-1"},[t("真的超讚！用systemd命令來管理linux系統！ "),n("a",{class:"header-anchor",href:"#真的超讚-用systemd命令來管理linux系統","aria-label":"Permalink to “真的超讚！用systemd命令來管理linux系統！”"},"​")],-1)),e[19]||(e[19]=n("p",null,"Systemd是一種新的linux系統服務管理器。",-1)),n("p",null,[e[2]||(e[2]=t("它替換了init系統，能夠管理系統的啓動過程和一些系統服務，一旦啓動起來，就將監管整個系統。在本文中，我們用的是",-1)),a(s,{href:"http://linoxide.com/linux-how-to/install-systemd-centos-redhat/"},{default:o(()=>[...e[0]||(e[0]=[t("安裝有 systemd 216 版本的centos 7.0",-1)])]),_:1}),e[3]||(e[3]=t("，其最新版本",-1)),a(s,{href:"http://www.freedesktop.org/software/systemd/"},{default:o(()=>[...e[1]||(e[1]=[t("可以從 freedesktop.org 下載得到",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))]),e[20]||(e[20]=d(`<p>因為linux操作系統裏出現的這一個新人，PID 1被“systemd”佔據了，這能通過<strong>pstree</strong>命令看到。</p><pre><code>[root@linoxide ~]# pstree
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/01.systemd_pstree.png" alt=""></p><p>那麼現在讓我們來探索systemd擅長什麼，它又有多大的可能性成為sysVinit的新的替代品。</p><h3 id="_1-更快啓動" tabindex="-1">1. 更快啓動 <a class="header-anchor" href="#_1-更快啓動" aria-label="Permalink to “1. 更快啓動”">​</a></h3><p>sysvinit一次一個串行地啓動進程。</p><p>而Systemd則並行地啓動系統服務進程，並且最初僅啓動確實被依賴的那些服務，極大地減少了系統引導的時間。</p><p>你可以用下面的命令看到系統引導用時：</p><pre><code>[root@linoxide ~]# systemd-analyze
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/02.systemd_analyze.png" alt=""></p><p>使用 <strong>time</strong> 參數也能夠顯示同樣的內容。</p><pre><code>[root@linoxide ~]# systemd-analyze time
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/03.systemd_analyze2.png" alt=""></p><p>如果你想以進程初始化所佔用時間排序打印出所有正在運行的單元列表，那麼<strong>systemd-analyze</strong>命令可以幫助你完成這個任務。</p><pre><code>[root@linoxide ~]# systemd-analyze blame
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/04.systemd_blame.png" alt=""></p><p>上面的截屏只顯示了小部分進程，你可以就像less分頁器那樣用箭頭滾動列表。</p><h3 id="_2-systemctl-命令" tabindex="-1">2. systemctl 命令 <a class="header-anchor" href="#_2-systemctl-命令" aria-label="Permalink to “2.  systemctl 命令”">​</a></h3><p>systemctl命令是自systemd出現以來被廣泛討論的命令。你可以通過這個命令管理你的整個系統，讓我們通過探究這個命令來更進一步。</p><h4 id="_2-1-列出單元" tabindex="-1">2.1 列出單元 <a class="header-anchor" href="#_2-1-列出單元" aria-label="Permalink to “2.1 列出單元”">​</a></h4><p><strong>systemctl</strong>命令可以帶上list-units，也可以什麼選項都不帶來列出所有正在運行的單元。</p><pre><code>[root@linoxide ~]# systemctl
</code></pre><p>或</p><pre><code>[root@linoxide ~]# systemctl list-units
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/05.systemd_list_units.png" alt=""></p><h4 id="_2-2-列出失敗的單元" tabindex="-1">2.2 列出失敗的單元 <a class="header-anchor" href="#_2-2-列出失敗的單元" aria-label="Permalink to “2.2 列出失敗的單元”">​</a></h4><p>運行失敗的單元可以用帶--failed選項的命令顯示出來。</p><pre><code>[root@linoxide ~]# systemctl --failed
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/06.systemd_failed.png" alt=""></p><p>你可以在這篇文章很多地方看到systemctl的用法。</p><h3 id="_3-管理服務" tabindex="-1">3. 管理服務 <a class="header-anchor" href="#_3-管理服務" aria-label="Permalink to “3. 管理服務”">​</a></h3><p>讓我們來看看systemd是怎麼管理系統服務的。</p><h4 id="_3-1-激活的服務" tabindex="-1">3.1 激活的服務 <a class="header-anchor" href="#_3-1-激活的服務" aria-label="Permalink to “3.1 激活的服務”">​</a></h4><p>所有被激活的服務可以同下面這條命令來查看。</p><pre><code>[root@linoxide ~]# systemctl list-units -t service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/07.systemd_active_services.png" alt=""></p><h4 id="_3-2-服務狀態" tabindex="-1">3.2 服務狀態 <a class="header-anchor" href="#_3-2-服務狀態" aria-label="Permalink to “3.2 服務狀態”">​</a></h4><p>在sysvinit中，我們可以用“<strong>service</strong>”命令來管理服務，但在systemd中，我們用systemctl這個命令。 我們可以用下面這個命令來查看服務是否在運行。</p><pre><code>[root@linoxide ~]# systemctl status dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/08.systemd_status.png" alt=""></p><h4 id="_3-3-啓動一個服務" tabindex="-1">3.3 啓動一個服務 <a class="header-anchor" href="#_3-3-啓動一個服務" aria-label="Permalink to “3.3 啓動一個服務”">​</a></h4><p>用下面這條命令來啓動服務。</p><pre><code>[root@linoxide ~]# systemctl start dnsmasq
</code></pre><p>對應於<strong>service</strong>命令，這個命令不進行輸出。但是毋庸置疑，我們可以通過再次查看這個剛剛被啓動的服務的status（狀態）來確認他是否被成功地啓動了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/09.systemd_start.png" alt=""></p><h4 id="_3-4-停止一個服務" tabindex="-1">3.4 停止一個服務 <a class="header-anchor" href="#_3-4-停止一個服務" aria-label="Permalink to “3.4 停止一個服務”">​</a></h4><p>現在聰明的你一定知道怎麼在systemd下用命令來關閉服務了吧。</p><pre><code>[root@linoxide ~]# systemctl stop dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/10.systemd_stop.png" alt=""></p><h4 id="_3-5-重啓一個服務" tabindex="-1">3.5 重啓一個服務 <a class="header-anchor" href="#_3-5-重啓一個服務" aria-label="Permalink to “3.5 重啓一個服務”">​</a></h4><p>類似的，重啓系統服務是用‘<strong>systemctl restart</strong>’來管理的。</p><pre><code>[root@linoxide ~]# systemctl restart dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/11.systemd_restart.png" alt=""></p><h4 id="_3-6-重新加載一個服務" tabindex="-1">3.6 重新加載一個服務 <a class="header-anchor" href="#_3-6-重新加載一個服務" aria-label="Permalink to “3.6 重新加載一個服務”">​</a></h4><p>在我們需要重新加載服務的配置文件又不想重啓這個服務（例如ssh）時，我們可以用這個命令。</p><pre><code>[root@linoxide ~]# systemctl reload sshd
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/12.systemd_reload.png" alt=""></p><p>雖然上述幾個命令的語法是可以工作的，但是官方文檔建議我們用下面這種語法形式來運行命令（LCTT 譯註，即使用在服務名後面跟上“.service”的完整名稱）：</p><pre><code>[root@linoxide ~]# systemctl status dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/13.systemd_alternate_syntax.png" alt=""></p><h3 id="_4-管理引導時的服務" tabindex="-1">4. 管理引導時的服務 <a class="header-anchor" href="#_4-管理引導時的服務" aria-label="Permalink to “4. 管理引導時的服務”">​</a></h3><p><strong>chkconfig</strong>命令被用來管理系統引導時的服務。同樣用systemd也可以管理引導時的系統服務。</p><h4 id="_4-1-檢查服務引導時是否運行" tabindex="-1">4.1 檢查服務引導時是否運行 <a class="header-anchor" href="#_4-1-檢查服務引導時是否運行" aria-label="Permalink to “4.1 檢查服務引導時是否運行”">​</a></h4><p>這條命令用來確定服務是否是引導時啓動的。</p><pre><code>[root@linoxide ~]# systemctl is-enabled dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/14.systemd_is_enabled.png" alt=""></p><h4 id="_4-2-讓服務在引導時運行" tabindex="-1">4.2 讓服務在引導時運行 <a class="header-anchor" href="#_4-2-讓服務在引導時運行" aria-label="Permalink to “4.2 讓服務在引導時運行”">​</a></h4><p><strong>systemctl</strong>命令是這樣來enable（使之在引導時啓動）一個服務的。（這相當於sysvinit中的‘<strong>chkconfig on</strong>’）</p><pre><code>[root@linoxide ~]# systemctl enable dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/15.systemd_enable.png" alt=""></p><h4 id="_4-3-取消服務在引導時運行" tabindex="-1">4.3 取消服務在引導時運行 <a class="header-anchor" href="#_4-3-取消服務在引導時運行" aria-label="Permalink to “4.3 取消服務在引導時運行”">​</a></h4><p>類似的，使服務不在引導時啓動用這個命令。</p><pre><code>[root@linoxide ~]# systemctl disable dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/16.systemd_disable.png" alt=""></p><h3 id="_5-管理遠程系統" tabindex="-1">5. 管理遠程系統 <a class="header-anchor" href="#_5-管理遠程系統" aria-label="Permalink to “5. 管理遠程系統”">​</a></h3><p>所有剛才提到的systemctl命令通常都能被用來管理遠程主機，完成這個任務將用到<strong>ssh</strong>來進行通訊。你只需要像這樣將遠程主機和用户名添加到systemctl命令後。</p><pre><code>[root@linoxide ~]# systemctl status sshd -H root@1.2.3.4
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/17.systemd_remote.png" alt=""></p><h3 id="_6-管理目標" tabindex="-1">6. 管理目標 <a class="header-anchor" href="#_6-管理目標" aria-label="Permalink to “6. 管理目標”">​</a></h3><p>Systemd有一個完成與sysVinit的runlevels相似任務的構想。</p><p>sysVinit的runlevels大多是以數字分級的。這裏是runlevers在systemd中的對應元素。</p><blockquote><p>0 runlevel0.target, poweroff.target</p><p>1, s, single runlevel1.target, rescue.target</p><p>2, 4 runlevel2.target, runlevel4.target, multi-user.target</p><p>3 runlevel3.target, multi-user.target</p><p>5 runlevel5.target, graphical.target</p><p>6 runlevel6.target, reboot.target</p><p>emergency emergency.target</p></blockquote><h4 id="_6-1-改變當前目標" tabindex="-1">6.1 改變當前目標 <a class="header-anchor" href="#_6-1-改變當前目標" aria-label="Permalink to “6.1 改變當前目標”">​</a></h4><p>當前target可以用這個命令切換。</p><pre><code>[root@linoxide ~]# systemctl isolate graphical.target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/18.systemd_isolate.png" alt=""></p><h4 id="_6-2-列出當前目標" tabindex="-1">6.2 列出當前目標 <a class="header-anchor" href="#_6-2-列出當前目標" aria-label="Permalink to “6.2 列出當前目標”">​</a></h4><p>如果你想查看你正處於哪個target中，你需要列出相應的單元。雖然這樣操作可能讓你不太爽，但是這就是systemd工作的方式。</p><pre><code>[root@linoxide ~]# systemctl list-units --type=target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/19.systemd_targets.png" alt=""></p><p>你可以看到“graphical.target”列在此處，這就是我們剛才切換到的目標。現在，讓我們切換runlevel到multi-user.target，然後分析下列命令的輸出。</p><pre><code>[root@linoxide ~]# systemctl isolate multi-user.target
[root@linoxide ~]# systemctl list-units --type=target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/20.systemd_multi-user.png" alt=""></p><h4 id="_6-3-列出默認目標" tabindex="-1">6.3 列出默認目標 <a class="header-anchor" href="#_6-3-列出默認目標" aria-label="Permalink to “6.3 列出默認目標”">​</a></h4><p>用這個systemctl命令來查看默認目標。</p><pre><code>[root@linoxide ~]# systemctl get-default
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/21.systemd_get_default.png" alt=""></p><h4 id="_6-4-改變默認目標" tabindex="-1">6.4 改變默認目標 <a class="header-anchor" href="#_6-4-改變默認目標" aria-label="Permalink to “6.4 改變默認目標”">​</a></h4><p>通過systemctl的set-default命令可以將某個目標設置成默認目標。</p><pre><code>[root@linoxide ~]# systemctl set-default graphical.target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/22.systemd_set_default.png" alt=""></p><h3 id="_7-記錄-systemd-的日誌" tabindex="-1">7. 記錄 systemd 的日誌 <a class="header-anchor" href="#_7-記錄-systemd-的日誌" aria-label="Permalink to “7. 記錄 systemd 的日誌”">​</a></h3><p>journald是systemd獨有的日誌系統，替換了sysVinit中的syslog守護進程。命令<strong>journalctl</strong>用來讀取日誌。</p><pre><code>[root@linoxide ~]# journalctl
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/23.systemd_logs.png" alt=""></p><h4 id="_7-1-查看引導信息" tabindex="-1">7.1 查看引導信息 <a class="header-anchor" href="#_7-1-查看引導信息" aria-label="Permalink to “7.1 查看引導信息”">​</a></h4><p>運行<strong>journalctl -b</strong>命令來查看所有引導日誌。</p><pre><code>[root@linoxide ~]# journalctl -b
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/24.systemd_boot.png" alt=""></p><h4 id="_7-2-即時顯示引導日誌" tabindex="-1">7.2 即時顯示引導日誌 <a class="header-anchor" href="#_7-2-即時顯示引導日誌" aria-label="Permalink to “7.2 即時顯示引導日誌”">​</a></h4><p>下面這個命令可以實時顯示系統日誌（類似<strong>tail -f</strong>）。</p><pre><code>[root@linoxide ~]# journalctl -f
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/25.systemd_follow_logs.png" alt=""></p><h4 id="_7-3-查看特定服務的日誌" tabindex="-1">7.3 查看特定服務的日誌 <a class="header-anchor" href="#_7-3-查看特定服務的日誌" aria-label="Permalink to “7.3 查看特定服務的日誌”">​</a></h4><p>你可以像這樣運用<strong>journalctl</strong>來查看你只想看到的服務或可執行程序的日誌。</p><pre><code>[root@linoxide ~]# journalctl /usr/sbin/dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/26.systemd_specific.png" alt=""></p><h3 id="_8-電源管理" tabindex="-1">8. 電源管理 <a class="header-anchor" href="#_8-電源管理" aria-label="Permalink to “8. 電源管理”">​</a></h3><p>systemctl命令也可以用來關機，重啓或者休眠。</p><p>要關機、重啓、掛起和休眠，分別使用如下命令：</p><pre><code>[root@linoxide ~]# systemctl poweroff

[root@linoxide ~]# systemctl reboot

[root@linoxide ~]# systemctl suspend

[root@linoxide ~]# systemctl hibernate
</code></pre><h3 id="_9-又及" tabindex="-1">9. 又及 <a class="header-anchor" href="#_9-又及" aria-label="Permalink to “9. 又及”">​</a></h3><p><strong>systemd</strong>帶來了一整套與操作系統交互的新途徑，並且極具特色。舉個栗子，你可以用hostnamectl命令來獲得你的linux機器的hostname和其它有用的獨特信息。</p><pre><code>[root@linoxide ~]# hostnamectl
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/27.systemd_hostnamectl.png" alt=""></p><hr>`,126)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),a(s,{href:"http://linoxide.com/linux-command/linux-systemd-commands/"},{default:o(()=>[...e[5]||(e[5]=[t("http://linoxide.com/linux-command/linux-systemd-commands/",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("作者：",-1)),a(s,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[7]||(e[7]=[t("Raghu",-1)])]),_:1}),e[11]||(e[11]=t(" 譯者：",-1)),a(s,{href:"https://github.com/szrlee"},{default:o(()=>[...e[8]||(e[8]=[t("szrlee",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...e[9]||(e[9]=[t(" wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創翻譯，",-1)),a(s,{href:"http://linux.cn/"},{default:o(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const w=r(m,[["render",c]]);export{f as __pageData,w as default};
